#!/usr/bin/env python3
"""Regenerates the generated parts of the set files, in place.

  python3 gen/sets.py           rewrite the regions between the lines
                                "# BEGIN GENERATED by gen/sets.py: <name>"
                                and "# END GENERATED: <name>"
  python3 gen/sets.py --check   only check that they are up to date

Each set of access rights (filesystem, network, scoping) is a record of one
Bool per right, in the kernel's bit order. The tables below are the only
place the rights are listed; a new right is a new row (and its ABI version
in abi.bend). The regions are: the right's enumeration and the set's record,
the right's index (its bit number), name and the list of all rights, the
set as a list of Bools and back, and the set of one right. Also the region
"fs_has" of PROOF.bend (16 cases of the lemma has_of_bools) and the same for
the other sets.
"""
import os, sys

# (constructor, record field, kernel name)
FS = [
    ("LandlockExecute", "execute", "EXECUTE"),
    ("LandlockWriteFile", "write_file", "WRITE_FILE"),
    ("LandlockReadFile", "read_file", "READ_FILE"),
    ("LandlockReadDir", "read_dir", "READ_DIR"),
    ("LandlockRemoveDir", "remove_dir", "REMOVE_DIR"),
    ("LandlockRemoveFile", "remove_file", "REMOVE_FILE"),
    ("LandlockMakeChar", "make_char", "MAKE_CHAR"),
    ("LandlockMakeDir", "make_dir", "MAKE_DIR"),
    ("LandlockMakeReg", "make_reg", "MAKE_REG"),
    ("LandlockMakeSock", "make_sock", "MAKE_SOCK"),
    ("LandlockMakeFifo", "make_fifo", "MAKE_FIFO"),
    ("LandlockMakeBlock", "make_block", "MAKE_BLOCK"),
    ("LandlockMakeSym", "make_sym", "MAKE_SYM"),
    ("LandlockRefer", "refer", "REFER"),
    ("LandlockTruncate", "truncate", "TRUNCATE"),
    ("LandlockIoctlDev", "ioctl_dev", "IOCTL_DEV"),
]
NET = [
    ("LandlockBindTcp", "bind_tcp", "BIND_TCP"),
    ("LandlockConnectTcp", "connect_tcp", "CONNECT_TCP"),
]
SCOPE = [
    ("LandlockScopeAbstractUnix", "abstract_unix_socket", "ABSTRACT_UNIX_SOCKET"),
    ("LandlockScopeSignal", "signal", "SIGNAL"),
]
# file, set type, right type, Bits prefix (how the file names LandlockBits), rows
SETS = [
    ("rights.bend", "LandlockFs", "LandlockFsRight", "", FS),
    ("net.bend", "LandlockNet", "LandlockNetRight", "R.", NET),
    ("scope.bend", "LandlockScope", "LandlockScopeRight", "R.", SCOPE),
]

def nat(k):
    return "%dn" % k

def types(T, TR, rows):
    out = ["type %s is Data:" % TR]
    out += ["  %s{}" % c for c, f, k in rows]
    out += ["", "type %s is Data:" % T]
    out.append("  %s{%s}" % (T, ", ".join("%s: Bool" % f for c, f, k in rows)))
    return "\n".join(out) + "\n"

def defs(T, TR, bits, rows):
    n = len(rows)
    out = []
    out.append("# the right's bit number in the kernel's mask")
    out.append("def %s.index(r: %s) -> Nat:" % (TR, TR))
    out.append("  match r:")
    for i, (c, f, k) in enumerate(rows):
        out += ["    case %s{}:" % c, "      %s" % nat(i)]
    out.append("")
    out.append("# the kernel's name, less its LANDLOCK_ prefix")
    out.append("def %s.name(r: %s) -> String:" % (TR, TR))
    out.append("  match r:")
    for c, f, k in rows:
        out += ["    case %s{}:" % c, '      "%s"' % k]
    out.append("")
    out.append("# every right, in bit order")
    out.append("def %s.all() -> List<&2, %s>:" % (TR, TR))
    out.append("  [%s]" % ", ".join("%s{}" % c for c, f, k in rows))
    out.append("")
    out.append("# the set as one Bool per right, in bit order")
    out.append("def %s.bools(s: %s) -> List<&2, Bool>:" % (T, T))
    out.append("  match s:")
    out.append("    case %s{%s}:" % (T, ", ".join(f for c, f, k in rows)))
    out.append("      [%s]" % ", ".join(f for c, f, k in rows))
    out.append("")
    out.append("# the set whose right i is element i of xs (False past the end)")
    out.append("def %s.of_bools(+xs: List<&2, Bool>) -> %s:" % (T, T))
    out.append("  %s{%s}" % (T, ", ".join("%sLandlockBits.nth(%s, xs)" % (bits, nat(i)) for i in range(n))))
    out.append("")
    out.append("# the set of one right")
    out.append("def %s.single(r: %s) -> %s:" % (T, TR, T))
    out.append("  match r:")
    for i, (c, f, k) in enumerate(rows):
        vals = ", ".join("True{}" if j == i else "False{}" for j in range(n))
        out += ["    case %s{}:" % c, "      %s{%s}" % (T, vals)]
    return "\n".join(out) + "\n"

OPS = r"""def @T@.has(s: @T@, r: @TR@) -> Bool:
  @B@LandlockBits.nth(@TR@.index(r), @T@.bools(s))

def @T@.none() -> @T@:
  @T@.of_bools(Nil{})

def @T@.all() -> @T@:
  @T@.of_bools(@B@LandlockBits.trues(@N@))

def @T@.union(a: @T@, b: @T@) -> @T@:
  @T@.of_bools(@B@LandlockBits.zor(@T@.bools(a), @T@.bools(b)))

def @T@.inter(a: @T@, b: @T@) -> @T@:
  @T@.of_bools(@B@LandlockBits.zand(@T@.bools(a), @T@.bools(b)))

def @T@.minus(a: @T@, b: @T@) -> @T@:
  @T@.of_bools(@B@LandlockBits.zminus(@T@.bools(a), @T@.bools(b)))

def @T@.subset(a: @T@, b: @T@) -> Bool:
  @B@LandlockBits.sub(@T@.bools(a), @T@.bools(b))

def @T@.is_empty(s: @T@) -> Bool:
  Bool.not(@B@LandlockBits.any(@T@.bools(s)))

def @T@.is_eq(+a: @T@, +b: @T@) -> Bool:
  Bool.and(@T@.subset(a, b), @T@.subset(b, a))

def @T@.add(s: @T@, r: @TR@) -> @T@:
  @T@.union(s, @T@.single(r))

def @T@.of_list(rs: List<&2, @TR@>) -> @T@:
  match rs:
    case Nil{}:
      @T@.none()
    case Con{r, t}:
      @T@.union(@T@.single(r), @T@.of_list(t))

def @T@.to_list.put(keep: Bool, r: @TR@, rest: List<&2, @TR@>) -> List<&2, @TR@>:
  match keep:
    case True{}:
      Con{r, rest}
    case False{}:
      rest

def @T@.to_list.go(xs: List<&2, @TR@>, +s: @T@) -> List<&2, @TR@>:
  match xs:
    case Nil{}:
      Nil{}
    case Con{+r, t}:
      @T@.to_list.put(@T@.has(s, r), r, @T@.to_list.go(t, s))

# the rights in the set, in bit order
def @T@.to_list(s: @T@) -> List<&2, @TR@>:
  @T@.to_list.go(@TR@.all(), s)

def @T@.names(xs: List<&2, @TR@>) -> List<&2, String>:
  match xs:
    case Nil{}:
      Nil{}
    case Con{r, t}:
      Con{@TR@.name(r), @T@.names(t)}

# the rights' names joined by "|"; "0" for the empty set
def @T@.show(s: @T@) -> String:
  @B@LandlockBits.join(@T@.names(@T@.to_list(s)))

def @T@.to_u32(s: @T@) -> U32:
  @B@LandlockBits.to_u32(@T@.bools(s), 1)

# the kernel's mask, a __u64 (bit i for right i)
def @T@.to_mask(s: @T@) -> W.W64:
  W.W64.from_u32(@T@.to_u32(s))

def @T@.of_mask.go(ok: Bool, lo: U32) -> Result<&2, &2, @E@LandlockError, @T@>:
  match ok:
    case True{}:
      Done{@T@.of_bools(@B@LandlockBits.of_u32(@N@, lo))}
    case False{}:
      Fail{@E@LandlockUnknownAccess{}}

# a kernel mask as a set; a bit no ABI defines is LandlockUnknownAccess
def @T@.of_mask(+m: W.W64) -> Result<&2, &2, @E@LandlockError, @T@>:
  +lo = W.W64.lo(m)
  @T@.of_mask.go(Bool.and(U32.is_eq(W.W64.hi(m), 0), U32.is_eq(U32.shrn(lo, @N@), 0)), lo)

"""

def ops(T, TR, bits, rows):
    return OPS.replace("@TR@", TR).replace("@T@", T).replace("@B@", bits).replace("@E@", "E.").replace("@N@", nat(len(rows)))

LEMMAS = r"""# @T@: what has answers on a set built from Bools, and on the set operations

def @P@.has_of_bools(+xs: List<&2, Bool>, +r: @M@@TR@) -> {@M@@T@.has(@M@@T@.of_bools(xs), r) == R.LandlockBits.nth(@M@@TR@.index(r), xs) : Bool}:
  match r:
@CASES@
def @P@.has_inter(+a: @M@@T@, +b: @M@@T@, +r: @M@@TR@) -> {@M@@T@.has(@M@@T@.inter(a, b), r) == Bool.and(@M@@T@.has(a, r), @M@@T@.has(b, r)) : Bool}:
  Equal.trans(Bool, @M@@T@.has(@M@@T@.inter(a, b), r), R.LandlockBits.nth(@M@@TR@.index(r), R.LandlockBits.zand(@M@@T@.bools(a), @M@@T@.bools(b))), Bool.and(@M@@T@.has(a, r), @M@@T@.has(b, r)), @P@.has_of_bools(R.LandlockBits.zand(@M@@T@.bools(a), @M@@T@.bools(b)), r), bits.nth_zand(@M@@TR@.index(r), @M@@T@.bools(a), @M@@T@.bools(b)))

def @P@.has_union(+a: @M@@T@, +b: @M@@T@, +r: @M@@TR@) -> {@M@@T@.has(@M@@T@.union(a, b), r) == Bool.or(@M@@T@.has(a, r), @M@@T@.has(b, r)) : Bool}:
  Equal.trans(Bool, @M@@T@.has(@M@@T@.union(a, b), r), R.LandlockBits.nth(@M@@TR@.index(r), R.LandlockBits.zor(@M@@T@.bools(a), @M@@T@.bools(b))), Bool.or(@M@@T@.has(a, r), @M@@T@.has(b, r)), @P@.has_of_bools(R.LandlockBits.zor(@M@@T@.bools(a), @M@@T@.bools(b)), r), bits.nth_zor(@M@@TR@.index(r), @M@@T@.bools(a), @M@@T@.bools(b)))

def @P@.has_none(+r: @M@@TR@) -> {@M@@T@.has(@M@@T@.none(), r) == False{} : Bool}:
  Equal.trans(Bool, @M@@T@.has(@M@@T@.none(), r), R.LandlockBits.nth(@M@@TR@.index(r), Nil{}), False{}, @P@.has_of_bools(Nil{}, r), bits.nth_nil(@M@@TR@.index(r)))

def @P@.subset_has(+a: @M@@T@, +b: @M@@T@, +r: @M@@TR@, +h1: {@M@@T@.subset(a, b) == True{} : Bool}, +h2: {@M@@T@.has(a, r) == True{} : Bool}) -> {@M@@T@.has(b, r) == True{} : Bool}:
  bits.sub_nth(@M@@TR@.index(r), @M@@T@.bools(a), @M@@T@.bools(b), h1, h2)

def @P@.subset_false(+a: @M@@T@, +b: @M@@T@, +r: @M@@TR@, +h1: {@M@@T@.has(a, r) == True{} : Bool}, +h2: {@M@@T@.has(b, r) == False{} : Bool}) -> {@M@@T@.subset(a, b) == False{} : Bool}:
  bits.sub_false(@M@@TR@.index(r), @M@@T@.bools(a), @M@@T@.bools(b), h1, h2)

def @P@.has_inter_intro(+a: @M@@T@, +b: @M@@T@, +r: @M@@TR@, +ha: {@M@@T@.has(a, r) == True{} : Bool}, +hb: {@M@@T@.has(b, r) == True{} : Bool}) -> {@M@@T@.has(@M@@T@.inter(a, b), r) == True{} : Bool}:
  Equal.trans(Bool, @M@@T@.has(@M@@T@.inter(a, b), r), Bool.and(@M@@T@.has(a, r), @M@@T@.has(b, r)), True{}, @P@.has_inter(a, b, r), b.and_intro(@M@@T@.has(a, r), @M@@T@.has(b, r), ha, hb))

def @P@.has_union_l(+a: @M@@T@, +b: @M@@T@, +r: @M@@TR@, +h: {@M@@T@.has(a, r) == True{} : Bool}) -> {@M@@T@.has(@M@@T@.union(a, b), r) == True{} : Bool}:
  Equal.trans(Bool, @M@@T@.has(@M@@T@.union(a, b), r), Bool.or(@M@@T@.has(a, r), @M@@T@.has(b, r)), True{}, @P@.has_union(a, b, r), b.or_true_l(@M@@T@.has(a, r), @M@@T@.has(b, r), h))

"""

def cases(mod, rows):
    out = []
    for c, f, k in rows:
        out += ["    case %s.%s{}:" % (mod, c), "      {==}"]
    return "\n".join(out) + "\n"

def lemmas(P, M, T, TR, rows):
    return LEMMAS.replace("@P@", P).replace("@M@", M + ".").replace("@T@", T).replace("@TR@", TR).replace("@CASES@", cases(M, rows))

def regions_for(fname):
    for f, T, TR, bits, rows in SETS:
        if f == fname:
            return {"types": types(T, TR, rows), "defs": defs(T, TR, bits, rows), "ops": ops(T, TR, bits, rows)}
    return {}

KINDS = ["LandlockReg", "LandlockDir", "LandlockChr", "LandlockBlk", "LandlockFifo", "LandlockSock", "LandlockSym"]

PROOF_REGIONS = {
    "sets": lemmas("fs", "R", "LandlockFs", "LandlockFsRight", FS) + lemmas("nt", "N", "LandlockNet", "LandlockNetRight", NET) + lemmas("sp", "S", "LandlockScope", "LandlockScopeRight", SCOPE),
    "fs_cases": cases("R", FS),
    "fs_cases2": cases("R", FS),
    "net_cases": cases("N", NET),
    "net_cases2": cases("N", NET),
    "scope_cases": cases("S", SCOPE),
    "scope_cases2": cases("S", SCOPE),
}

def rewrite(path, regions, check):
    if not os.path.exists(path):
        return True
    text = open(path).read()
    new = text
    for name, body in regions.items():
        b = "# BEGIN GENERATED by gen/sets.py: %s\n" % name
        e = "# END GENERATED: %s\n" % name
        if b not in new:
            continue
        i = new.index(b) + len(b)
        j = new.index(e)
        new = new[:i] + body + new[j:]
    if new != text:
        if check:
            print("out of date:", path)
            return False
        open(path, "w").write(new)
    return True

def main():
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
    check = "--check" in sys.argv
    ok = True
    for f, T, TR, bits, rows in SETS:
        ok &= rewrite(os.path.join(here, f), regions_for(f), check)
    ok &= rewrite(os.path.join(here, "PROOF.bend"), PROOF_REGIONS, check)
    sys.exit(0 if ok else 1)

main()
